	AND (perms is null or perms = '' or perms not like 'tenant:%')
	AND not exists (select 1 from sys_menu tenant_child where tenant_child.parent_id = sys_menu.fun_code and tenant_child.perms like 'tenant:%')

		AND menu_name like concat('%', #{menuName}, '%')


		AND visible = #{visible}


		AND status = #{status}


order by parent_id, order_num

select distinct m.fun_code, m.parent_id, m.menu_name, m.path, m.component, m.`query`, m.route_name, m.visible, m.status, ifnull(m.perms,'') as perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time from sys_menu m left join sys_role_menu rm on m.fun_code = rm.fun_code left join sys_user_role ur on rm.role_code = ur.role_code left join sys_role ro on ur.role_code = ro.role_code where ur.user_code = #{params.userCode} and ro.role_type = 'PLATFORM' and ro.shop_code = '' and (m.perms is null or m.perms = '' or m.perms not like 'tenant:%')
AND m.menu_name like concat('%', #{menuName}, '%')
AND m.visible = #{visible}
AND m.status = #{status}
order by m.parent_id, m.order_num

mapper.update:
update sys_menu
menu_name = #{menuName}, parent_id = #{parentId}, order_num = #{orderNum}, path = #{path}, component = #{component}, `query` = #{query}, route_name = #{routeName}, is_frame = #{isFrame}, is_cache = #{isCache}, menu_type = #{menuType}, visible = #{visible}, status = #{status}, perms = #{perms}, icon = #{icon}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where fun_code = #{funCode}
